+function CloseEmf(DC: HDC): HENHMETAFILE;
+var
+  brush, pen: HGDIOBJ;
+begin
+  brush := SelectObject(DC, GetStockObject(WHITE_BRUSH));
+  pen := SelectObject(DC, GetStockObject(NULL_PEN));
+  result := CloseEnhMetaFile(DC);
+  DeleteObject(brush); // a stock object is ignored
+  DeleteObject(pen);
+end;
